  Bluegill:['professional',245,235],Seahorse:['professional',470,235],Bowlfish:['professional',680,235],Bass:['professional',895,235],Eel:['professional',1110,235],
  'Red Snapper':['professional',245,450],Sengarat:['professional',470,450],Halibut:['professional',680,450],Tigerfish:['professional',895,450],'Flying Fish':['professional',1110,450],
  Voxelfish:['scientific',350,250],Parrotfish:['scientific',570,250],Dripper:['scientific',790,250],Blobfish:['scientific',1040,250],Oarfish:['scientific',1260,250],
  Anglerfish:['scientific',350,490],Stonefish:['scientific',570,490],'Superdwarf Fish':['scientific',790,490],Sunfish:['scientific',1040,490],'The Old Pike':['scientific',1260,490],
  'Blue Shark':['bosses',205,230],Tuna:['bosses',465,230],'Goblin Shark':['bosses',715,230],'Bowhead Whale':['bosses',950,230],'Spider Crab':['bosses',1200,230],
