function CreatureGallery(){const [active,setActive]=useState(0);const move=(delta:number)=>setActive(index=>(index+delta+creatureGallerySlides.length)%creatureGallerySlides.length);const slide=creatureGallerySlides[active];return <section className="creature-gallery" aria-label="In-game creature encyclopedia screenshots" aria-roledescription="carousel" tabIndex={0} onKeyDown={event=>{if(event.key==='ArrowLeft')move(-1);if(event.key==='ArrowRight')move(1)}}><figure><img src={slide.src} alt={slide.title}/><figcaption><span>{slide.label}</span><b>{slide.title}</b><small>{slide.caption}</small></figcaption></figure><div className="creature-gallery-controls"><button onClick={()=>move(-1)} aria-label="Previous encyclopedia image">←</button><div>{creatureGallerySlides.map((item,index)=><button key={item.src} className={index===active?'active':''} onClick={()=>setActive(index)} aria-label={`Show ${item.title}`} aria-current={index===active?'true':undefined}/>)}</div><b>{String(active+1).padStart(2,'0')} / {String(creatureGallerySlides.length).padStart(2,'0')}</b><button onClick={()=>move(1)} aria-label="Next encyclopedia image">→</button></div></section>}
function CreatureThumb({name}:{name:string}){const crop=creatureCropMap[name];if(!crop)return <span className="creature-thumb missing">Image<br/>pending</span>;const [sheetName,x,y]=crop;const sheet=creatureSheets[sheetName];const frameWidth=94,frameHeight=72,scale=sheet.scale*(frameWidth/86);const locked=name==='Goblin Shark'||name==='Mutated Bowhead Whale';return <span className={`creature-thumb ${locked?'locked':''}`} title={locked?'Captured locked silhouette from the in-game encyclopedia':`${name} in-game encyclopedia model`}><img src={sheet.src} alt="" aria-hidden="true" loading="lazy" style={{width:`${sheet.width*scale}px`,left:`${frameWidth/2-x*scale}px`,top:`${frameHeight/2-y*scale}px`}}/></span>}
function Creatures(){const [query,setQuery]=useState('');const [filter,setFilter]=useState('All');const [island,setIsland]=useState('All locations');const [caught,setCaught]=useState<string[]>([]);const [hydrated,setHydrated]=useState(false);useEffect(()=>{try{const raw=JSON.parse(localStorage.getItem('htf-caught')||'[]');const names=new Set(creatures.map(c=>c.name));if(Array.isArray(raw))setCaught([...new Set(raw.filter((item):item is string=>typeof item==='string'&&names.has(item)))]);}catch{}finally{setHydrated(true)}},[]);useEffect(()=>{if(hydrated)localStorage.setItem('htf-caught',JSON.stringify(caught))},[caught,hydrated]);const visible=useMemo(()=>creatures.filter(c=>(filter==='All'||c.kind===filter)&&(island==='All locations'||c.island===island)&&c.name.toLowerCase().includes(query.trim().toLowerCase())),[query,filter,island]);const toggle=(name:string)=>setCaught(current=>current.includes(name)?current.filter(value=>value!==name):[...current,name]);return <section className="hub creature-page"><Crumb>Creature Encyclopedia</Crumb><p className="eyebrow">ILLUSTRATED COLLECTION TOOL</p><h1>All 49 How to Fish<br/><i>Game Creatures</i></h1><p className="standfirst">Every regular catch, miniboss, and story creature in one illustrated, searchable log—with its progression location, lure or summon, and reported base value.</p><CreatureGallery/><section className="creature-intro"><div><span>49</span><b>normal entries</b><p>The in-game Tab encyclopedia tracks the ordinary set shown here.</p></div><div><span>49</span><b>Drip variants</b><p>Rare Drip versions use the same lure or trigger and are tracked separately.</p></div><div><span>5</span><b>route locations</b><p>Lighthouse → Forest → Desert → Rocks → Volcano.</p></div></section><div className="creature-note"><b>VALUE NOTE</b><span>Base values are identification references, not guaranteed sale prices. Weight, Killscore, cooking, Drip state, and later balance patches can change the final amount.</span></div><div className="progress"><span><b>{caught.length}</b> / 49 logged</span><div><i style={{width:`${caught.length/49*100}%`}}/></div></div><div className="filters creature-filters"><label><span className="sr-only">Search creatures</span><input value={query} onChange={event=>setQuery(event.target.value)} placeholder="Search creature name…"/></label><div>{['All','Creature','Boss / Special'].map(value=><button type="button" className={filter===value?'active':''} onClick={()=>setFilter(value)} key={value}>{value}</button>)}</div><label><span className="sr-only">Filter by location</span><select value={island} onChange={event=>setIsland(event.target.value)}>{['All locations','Lighthouse','Forest','Desert','Rocks','Volcano'].map(value=><option key={value}>{value}</option>)}</select></label></div><p className="creature-results">Showing <b>{visible.length}</b> of 49 entries</p><div className="creature-grid illustrated">{visible.map(creature=><label className={`creature illustrated-card ${caught.includes(creature.name)?'caught':''}`} key={creature.name}><input type="checkbox" checked={caught.includes(creature.name)} onChange={()=>toggle(creature.name)}/><CreatureThumb name={creature.name}/><span className="creature-card-copy"><span className="creature-card-top"><span className="check">✓</span><span className="number">{String(creatures.indexOf(creature)+1).padStart(2,'0')}</span><small>{creature.kind}</small></span><b>{creature.name}</b><span className="creature-meta"><span><i>LOCATION</i>{creature.island}</span><span><i>VALUE</i>${creature.value.toLocaleString()}</span></span><span className="creature-lure"><i>ROD / LURE / SUMMON</i>{creature.lure}</span></span></label>)}</div>{visible.length===0&&<p className="creature-empty">No creature matches these filters.</p>}<section className="hub-note creature-method"><h2>How to finish the encyclopedia</h2><ol><li>Open <b>Tab</b> in game and identify the exact blank slot.</li><li>Filter this page by the route location, then equip the listed rod, lure, or unique summon.</li><li>Land and defeat the creature so the normal encyclopedia entry registers.</li><li>Repeat the same trigger for the rare Drip variant; it belongs to the separate 49-entry Drip set.</li><li>Do not sell or cook a unique boss catch until the next quest objective is complete.</li></ol><p>Creature count and lure pools were checked against <a href="https://mobalytics.gg/gamebase/guides/how-to-fish-all-fish-creatures-lures" target="_blank" rel="noreferrer">Mobalytics’ current 49-creature guide ↗</a>. Game scope, co-op support, and collection premise are also described on the <a href="https://store.steampowered.com/app/4001890/How_to_Fish/" target="_blank" rel="noreferrer">official Steam page ↗</a>. The encyclopedia images on this page are owner-provided gameplay captures.</p></section></section>}
function BossProgression(){return <section className="hub-note boss-progression"><h2>The verified story-boss chain</h2><p>These encounters unlock the five-location route. Finish the NPC exchange after each fight; a defeated boss alone does not guarantee the next destination.</p><ol className="steps compact"><li><b>Forest — Giant Piranha.</b><span>Give three Leeches to the lake NPC, use the Modified Leech, defeat Giant Piranha, and return its Skeleton for the yellow Desert marker.</span></li><li><b>Desert — Pufferfish.</b><span>Complete the Tourist’s endangered-creature request, use the Carrot reward, and return the Pufferfish Fin for the red Rocks marker.</span></li><li><b>Rocks — Albatross.</b><span>Catch Tuna with the Professional Boss Lure, place it on land, defeat Albatross, and return its Head for the final coordinates.</span></li><li><b>Volcano — whale finale.</b><span>Catch five native creatures for the scientist, receive the Fish Bucket, catch Bowhead Whale, carry its body to the crater, defeat Mutated Bowhead Whale, and return the Whale Fin to the scientist for the military boat key.</span></li></ol><p>Open the <a href="/locations">five-location route guide</a> for readiness checks and failure recovery at every stop. The sequence is cross-checked against <a href="https://www.destructoid.com/complete-how-to-fish-game-walkthrough-100-completion/" target="_blank" rel="noreferrer">Destructoid’s complete walkthrough ↗</a> and <a href="https://mobalytics.gg/gamebase/guides/how-to-fish-unlock-every-island" target="_blank" rel="noreferrer">Mobalytics’ island guide ↗</a>.</p></section>}
function Bosses(){return <section className="hub"><Crumb>Boss Guides</Crumb><p className="eyebrow">SPECIAL ENCOUNTERS</p><h1>All How to Fish Game<br/><i>Bosses</i></h1><p className="standfirst">Eleven boss and special creatures sit outside the ordinary collection loop. Bring the specified item, then follow the route cue.</p><section className="hub-note"><h2>How to use this boss board</h2><p>Separate ordinary fishing from progression attempts. Named summons are route-specific, so equip one only when you are ready to finish the encounter. Before casting, bank anything you cannot afford to lose, carry food, and leave open ground for the fight. After the kill, inspect every unique drop before selling or eating anything.</p><p>The first fully illustrated route is <a href="/bosses/spider-crab">Spider Crab at Lighthouse</a>. It covers the Empty Beer Can trigger, the charge-and-stun combat loop, the shell hand-in, Boat Keys, and the Radar step. Other cards remain concise until their current-build routes have been independently frame-checked.</p></section><div className="boss-grid">{bosses.map((b,i)=><article className="boss" key={b.name}><span>0{i+1}</span><h2>{b.name}</h2><p>{b.note}</p><dl><div><dt>Summon</dt><dd>{b.summon}</dd></div><div><dt>Route</dt><dd>{b.route}</dd></div></dl>{b.name==='Spider Crab'&&<a href="/bosses/spider-crab">Read full guide →</a>}{b.name==='Albatross'&&<a href="/locations/rocks">Read Rocks &amp; Albatross guide →</a>}</article>)}</div><BossProgression/><section className="hub-note"><h2>Progression safety checklist</h2><ol><li>Confirm the summon item and location before casting.</li><li>Heal, save, and clear a safe combat lane.</li><li>Watch one attack cycle before committing damage.</li><li>Collect unique drops and complete the NPC hand-in.</li><li>Confirm the next key, coordinate, or marker before leaving.</li></ol><p>Patch changes can alter health, damage, and save behavior. Detailed guides show a checked date and source boundary so you can distinguish verified instructions from a simple entity list.</p></section></section>}
function Locations(){return <LocationsGuide/>}
function Lures(){const pools=[['Beginner Lure','The opening collection pool and early route progression.'],['Standard Lure','The next regular creature pool after early upgrades.'],['Professional Lure','A later collection pool for advanced progression.'],['Scientific Lure','The final regular lure tier.']];return <section className="hub"><Crumb>Lures &amp; Bait</Crumb><p className="eyebrow">COLLECTION SYSTEM</p><h1>How to Fish Game<br/><i>Lures &amp; Bait</i></h1><p className="standfirst">Lure tiers, not a fixed island-only fish table, shape regular creature collection. Bosses use separate named summons.</p><section className="hub-note"><h2>Regular pools and special summons are different</h2><p>Use the four regular lure tiers to expand the ordinary collection pool as your route advances. Named boss items are not generic upgrades: they target a specific encounter and can be wasted if you cast before preparing. Check the equipped item, destination, health, food, and inventory space before a special attempt.</p><p>This guide deliberately avoids assigning every ordinary creature to a lure without current-build proof. The searchable <a href="/creatures">49-creature checklist</a> records confirmed names, while the boss board lists special summon relationships with traceable guide evidence.</p></section><div className="lure-layout"><div>{pools.map(([title,copy],i)=><article className="lure" key={title}><span>POOL 0{i+1}</span><h2>{title}</h2><p>{copy}</p><a href="/creatures">Browse creature log →</a></article>)}</div><aside><p className="eyebrow">SPECIAL SUMMONS</p><h2>Boss items</h2>{bosses.slice(0,6).map(b=><p key={b.name}><b>{b.summon}</b><span>{b.name}</span></p>)}<a href="/bosses">All 11 summons →</a></aside></div><p className="fineprint">Exact regular-creature pool assignments are being kept conservative until independently verified in current game builds. Special summons listed here are cited in the research references.</p><section className="hub-note"><h2>Safe casting routine</h2><ol><li>Choose the target before selecting a lure.</li><li>Verify whether the item is a reusable pool lure or a named special summon.</li><li>Move to the route location and clear a landing area.</li><li>Equip food and the weapon needed for the catch.</li><li>Cast, keep the lure moving, and secure the catch away from water.</li></ol><p>For the first verified special item chain, see <a href="/bosses/spider-crab">Empty Beer Can → Spider Crab</a>. The guide shows what happens before the cast, during the stun window, and after the shell drops.</p></section></section>}
function SpiderCrab(){return <article className="article guide-article"><Crumb><><a href="/bosses">Boss Guides</a><span>›</span>Spider Crab</></Crumb><p className="eyebrow">BOSS 01 · LIGHTHOUSE</p><h1>How to Beat Spider Crab<br/><i>in How to Fish Game</i></h1><p className="standfirst">Spider Crab is the first Lighthouse boss. Summon it with the Empty Beer Can, fight the charge rather than the claws, then hand the shell to the fisherman for boat keys. This page separates the trigger, safe combat loop, and post-fight quest step so you do not lose an attempt to the wrong item.</p><Trust/>
<div className="quick-nav" aria-label="On this page"><b>QUICK ROUTE</b><a href="#summon">Summon it</a><a href="#combat">Combat loop</a><a href="#reward">Shell → keys</a><a href="#coop-recovery">Co-op revive</a><a href="#mistakes">Mistakes</a></div>
<div className="fact-row"><div><span>SUMMON</span><b>Empty Beer Can</b></div><div><span>LOCATION</span><b>Lighthouse shore</b></div><div><span>PROGRESSION</span><b>Shell → boat keys</b></div></div>
<GuideVisual src="/images/guides/spider-crab-combat-loop.svg" alt="Original diagram of the Spider Crab combat loop" caption="The boss is a rhythm check: hold space, sidestep the lunge, hit only during the self-stun, then reset the lane."/>
<section id="summon"><h2>1. Summon Spider Crab correctly</h2><p>PC Gamer and GamesRadar+ agree on the gate: complete the opening tutorial route, give the fisherman a full beer, then use the returned <strong>Empty Beer Can</strong> as bait. Standard bait is not the boss trigger.</p><ol className="steps"><li><b>Finish the opening tutorial.</b><span>PC Gamer begins its route with the sailor tutorial and early clam / fishing-rod objectives.</span></li><li><b>Prepare recovery.</b><span>PC Gamer recommends eating seafood before the fight and keeping a clam or two available if needed.</span></li><li><b>Trade beer for the empty can.</b><span>The full can is not the summon. Give it to the fisherman; the returned empty can is the special lure.</span></li><li><b>Equip and cast the empty can.</b><span>GamesRadar+ and PC Gamer both identify it as the bait used to reel in Spider Crab.</span></li></ol><div className="callout"><b>Source boundary:</b> cited written sources establish the item chain. Owner-supplied gameplay privately cross-checks the Empty Beer Can, Lighthouse, knife, and post-charge daze visuals; no source-video frame or account identifier is reproduced.</div></section>
<section id="combat"><h2>2. Use the charge → stun → punish loop</h2><p>GamesRadar+ describes Spider Crab’s main attack as a straight charge. Move out of that line, then attack once stars show the crab is stunned; leave again as it recovers. PC Gamer independently describes the post-attack dazed window and recommends patient hit-and-run attempts.</p><div className="combat-grid"><article><span>WAIT</span><b>Let the charge commit.</b><p>Keep your focus on avoiding the incoming line rather than attempting a hit before the attack resolves.</p></article><article><span>DODGE</span><b>Move out of the charge.</b><p>GamesRadar+ identifies this move as the boss’s primary attack and advises getting out of the way.</p></article><article><span>PUNISH</span><b>Attack while it is stunned.</b><p>Use the short window marked by stars / the dazed state, as described by GamesRadar+ and PC Gamer.</p></article><article><span>RESET</span><b>Leave as it recovers.</b><p>GamesRadar+ advises running away when it starts turning again, then waiting for the next charge.</p></article></div></section>
<section id="reward"><h2>3. The reward is a hand-in, not just a kill</h2><p>When Spider Crab goes down, keep the <strong>Spider Crab shell</strong> for the fisherman. PC Gamer and GamesRadar+ identify the shell hand-in as the step that awards boat keys. GamesRadar+ separately describes the radar tablet as the follow-up purchase for navigation.</p><GuideVisual src="/images/guides/spider-crab-handoff.svg" alt="Original diagram showing Spider Crab shell becoming boat keys and radar navigation" caption="Keep the shell separate until the fisherman has awarded the boat keys."/>
<ol className="steps compact"><li><b>Pick up the shell.</b><span>Inspect it and keep it out of the sell / food pile.</span></li><li><b>Give the shell to the fisherman.</b><span>Confirm the boat keys are awarded.</span></li><li><b>Get the radar and follow its marker.</b><span>The radar is a deliberate next step after keys, not a substitute for the quest hand-in.</span></li><li><b>Save after the unlock.</b><span>Official Patch 1.0.6 notes describe manual Save, Main Menu, Quit, and one-minute autosave behavior.</span></li></ol></section>
<section id="coop-recovery"><h2>Co-op recovery: create a revive window without losing the boss</h2><p>When a teammate is downed, stop chasing damage and make space around the body. The visible white bar is <strong>Spider Crab’s escape timer</strong>, not a revive countdown. One player should keep the boss engaged and redirect its charge away from the body while the other revives; the team must create a safe interaction window without letting the escape timer expire.</p><ol className="steps compact"><li><b>Call the down immediately.</b><span>The surviving player needs to know which side of the combat lane must be cleared.</span></li><li><b>Keep Spider Crab engaged.</b><span>Watch the white escape timer and stay close enough to prevent the encounter from ending.</span></li><li><b>Redirect the charge, then revive.</b><span>Pull the boss away from the body, start the revive only after the lane opens, and break off if the next charge threatens both players.</span></li><li><b>Reset before attacking.</b><span>Restore spacing and recovery rather than trading damage as soon as the teammate stands.</span></li></ol><div className="callout"><b>No fixed hit-count promise:</b> weapon choice, difficulty, and patches change damage. Use the visible daze and Spider Crab escape timer as encounter signals instead of memorizing a number of attacks.</div></section>
<section id="mistakes"><h2>Common mistakes and quick recoveries</h2><div className="troubleshoot"><article><b>Using a normal lure</b><span>Only the <strong>Empty Beer Can</strong> starts this boss. Redo the fisherman’s beer exchange if the lure in your rod is wrong.</span></article><article><b>Attacking during the charge</b><span>Stop trading hits. Create side room, dodge the lunge, and make your damage only while the crab is stunned.</span></article><article><b>Selling the Shell</b><span>Pick up the Spider Crab Shell, return it to the Lighthouse Keeper, and complete the hand-in for Boat Keys.</span></article><article><b>Leaving without navigation</b><span>Boat keys are not the last action. Acquire the radar and use the marker to leave Lighthouse cleanly.</span></article><article><b>Re-attempting while underprepared</b><span>Recover health and clear a lane first. If you are repeatedly dying, use Easy difficulty from the menu; Patch 1.0.9 documents its reduced creature health and damage.</span></article><article><b>Progress loss after a crash</b><span>Load and inspect before making more purchases. The official patch notes say crash-time writes were disabled while regular save points and a one-minute autosave remain.</span></article></div></section>
<Evidence items={[{label:'PC Gamer — Spider Crab strategy',url:'https://www.pcgamer.com/games/sim/how-to-fish-spider-crab/',note:'Written route: tutorial, Empty Beer Can bait, food recovery, dazed attack window, radar, Shell-to-Boat-Keys outcome.'},{label:'GamesRadar+ — Spider Crab guide',url:'https://www.gamesradar.com/games/co-op/how-to-fish-spider-crab/',note:'Written cross-check: Empty Beer Can bait, charge / stars-stun timing, Shell hand-in, Boat Keys, and separate Radar tablet.'},{label:'Dazed Games — current patch announcements',url:'https://steamcommunity.com/app/4001890/announcements/',note:'Official current-build maintenance source; the historical Patch 1.0.9 note remains the source for difficulty options.'}]}/>
<Related links={[["Beginner route: Lighthouse to Island 2","/beginner-guide"],["All boss & special creatures","/bosses"],["Lighthouse & main locations","/locations"]]}/></article>}
function Achievements(){return <section className="hub"><Crumb>Achievements</Crumb><p className="eyebrow">COMPLETION BOARD</p><h1>All 28 How to Fish<br/><i>Game Achievements</i></h1><p className="standfirst">A clean names checklist for completion-minded crews. Pair it with the creature log, boss board, and five-location route so you can diagnose which category a missing unlock belongs to.</p><section className="hub-note"><h2>Plan a 100% run without losing route progress</h2><p>Finish the tutorial and location unlock chain first, then clean up collection, equipment, stunt, food, and economy achievements. Route-first play gives you access to later lure pools and bosses while reducing the chance that a risky side objective costs a unique progression item.</p><p>This page does not invent unlock conditions where the current build has not been independently verified. Treat the list below as a completion board, not a substitute for the in-game achievement description. Detailed conditions will be added only after matching gameplay evidence or a reliable current-version source is available.</p></section><ol className="achievement-list">{achievements.map((a,i)=><li key={a}><span>{String(i+1).padStart(2,'0')}</span>{a}</li>)}</ol><section className="hub-note"><h2>Recommended cleanup order</h2><div className="editorial-grid"><article><b>1. Story and bosses</b><p>Complete every location hand-in and retain unique drops until the next route marker appears.</p></article><article><b>2. Collection</b><p>Use the local 49-creature checklist to mark confirmed catches without creating an account.</p></article><article><b>3. Equipment and economy</b><p>Buy missing upgrades after progression is safe, then work on money and gear milestones.</p></article><article><b>4. Skill and novelty</b><p>Leave speed, stunt, food, and unusual interaction achievements for a disposable cleanup save.</p></article></div><p>Your checklist state on this website remains in this browser only. It is not connected to Steam and cannot unlock or verify an achievement.</p></section></section>}
function About(){return <article className="article policy-page"><Crumb>About</Crumb><p className="eyebrow">INDEPENDENT PLAYER GUIDE</p><h1>About How to Fish<br/><i>Walkthrough</i></h1><p className="standfirst">How to Fish Walkthrough is an independent guide and checklist site for the 2026 Dazed Games title. It is not an official wiki and is not affiliated with Dazed Games, Steam, or the publishers cited in our research notes.</p><section><h2>What we publish</h2><p>We focus on steps a player can execute: what to prepare, where to go, what starts an encounter, how to recover from common mistakes, and what confirms progression. The Beginner Guide, Lighthouse route, and Spider Crab guide are the current editorial core.</p></section><section><h2>How guides are made</h2><p>Instructions are checked against owner-provided gameplay footage, official patch notes, and independent written walkthroughs. Original diagrams and processed frames explain mechanics. A visible checked date and evidence boundary distinguish frame-verified instructions from concise reference lists.</p></section><section><h2>Corrections and rights</h2><p>Games change quickly. If a patch changes a route, or if you own material that you believe appears without appropriate permission, use the <a href="/contact">contact page</a>. We review specific reports and correct or remove material when warranted.</p></section></article>}
function Contact(){return <article className="article policy-page"><Crumb>Contact</Crumb><p className="eyebrow">CORRECTIONS &amp; RIGHTS</p><h1>Contact the<br/><i>guide team</i></h1><p className="standfirst">Send a specific report for factual corrections, broken links, accessibility problems, privacy questions, or rights concerns.</p><section><h2>Best contact channel</h2><p>Open a public issue in the project repository: <a href="https://github.com/ShallowSummertime/fish/issues" target="_blank" rel="noreferrer">How to Fish Walkthrough issues ↗</a>. Include the affected URL, the sentence or image at issue, your evidence, and the game version when relevant. Do not post private account information.</p></section><section><h2>What to expect</h2><p>Actionable corrections are checked against the current build and cited sources. Rights requests should identify the material and explain your relationship to it. Spam, paid-link requests, and requests to manipulate rankings or ad clicks are ignored.</p></section></article>}
function Privacy(){return <article className="article policy-page"><Crumb>Privacy Policy</Crumb><p className="eyebrow">LAST UPDATED AUGUST 28, 2026</p><h1>Privacy<br/><i>Policy</i></h1><p className="standfirst">This policy explains what How to Fish Walkthrough stores, what third parties may receive, and the choices available to visitors.</p><section><h2>Information stored on your device</h2><p>The creature checklist uses browser local storage to remember names you mark as caught. That data remains on your device, is not tied to an account, and can be cleared through your browser settings or by clearing site data.</p></section><section><h2>Server and hosting data</h2><p>Our hosting provider may process standard request information such as IP address, device and browser details, requested URL, timestamp, and security logs to deliver and protect the site. We do not ask visitors to create an account or submit sensitive personal information.</p></section><section><h2>Advertising and cookies</h2><p>We may use Google AdSense to fund the site. Google and its partners may use cookies, web beacons, IP addresses, or similar technologies to serve, measure, and limit ads. Depending on your region and consent choices, ads may be personalized or non-personalized. Learn how Google uses information from sites that use its services at <a href="https://policies.google.com/technologies/partner-sites" target="_blank" rel="noreferrer">Google’s partner-sites policy ↗</a>.</p><p>Where required, visitors will be shown consent choices through a Google-certified consent management platform before advertising storage is used. You can manage ad personalization at <a href="https://myadcenter.google.com/" target="_blank" rel="noreferrer">My Ad Center ↗</a> and browser cookies through browser settings.</p></section><section><h2>External links and changes</h2><p>Research references and contact links lead to third-party sites with their own privacy practices. We may update this policy when hosting, analytics, advertising, or legal requirements change. Material changes will be reflected by the date at the top of this page.</p></section><section><h2>Questions</h2><p>Use the <a href="/contact">contact page</a> for privacy questions or requests.</p></section></article>}
function Terms(){return <article className="article policy-page"><Crumb>Terms &amp; Disclaimer</Crumb><p className="eyebrow">LAST UPDATED AUGUST 28, 2026</p><h1>Terms &amp;<br/><i>Disclaimer</i></h1><p className="standfirst">By using this site, you agree to use its guides as informational player-made material and to verify important steps against your current game build.</p><section><h2>Independent status</h2><p>How to Fish, Dazed Games, Steam, and related names, artwork, and trademarks belong to their respective owners. How to Fish Walkthrough is an unofficial fan resource and does not claim endorsement or partnership.</p></section><section><h2>Accuracy and availability</h2><p>We try to identify the checked version and source boundary for detailed guides, but patches can change mechanics, prices, saves, drops, and progression. The site is provided without a guarantee that every instruction will remain correct or that service will be uninterrupted.</p></section><section><h2>Acceptable use</h2><p>You may use the site for personal gameplay reference. Do not interfere with the site, attempt unauthorized access, scrape it in a way that degrades service, submit malicious reports, or reproduce original site text and illustrations as your own.</p></section><section><h2>Sources and takedown requests</h2><p>External sources are linked for verification; links do not transfer ownership or imply endorsement. Rights holders can submit a specific removal or correction request through the <a href="/contact">contact page</a>.</p></section></article>}
function NotFound(){return <section className="hub empty"><p className="eyebrow">OFF THE CHART</p><h1>This page drifted<br/><i>out of view.</i></h1><a className="button primary" href="/">Return to chart room <b>→</b></a></section>}
export function App({initialPath}:{initialPath?:string}){const path=initialPath??(typeof window==='undefined'?'/':window.location.pathname.replace(/\/$/,'')||'/');const Page=({'/':Home,'/beginner-guide':Beginner,'/creatures':Creatures,'/bosses':Bosses,'/locations':Locations,'/locations/lighthouse':LighthouseGuide,'/locations/rocks':RocksGuide,'/guides/reel-of-fortune':ReelOfFortuneGuide,'/lures':Lures,'/bosses/spider-crab':SpiderCrab,'/achievements':Achievements,'/about':About,'/contact':Contact,'/privacy':Privacy,'/terms':Terms}[path]||NotFound);return <><Meta path={path}/><Header/><main><Page/></main><Footer/></>};
